Path('apps/mobile/src/features/plugs/flows/readSavedBlePlugInformation.test.ts').write_text("""import { describe, expect, it, vi } from 'vitest';
import { BlePlugReadError } from '../data/blePlugReadError.js';
import type { PlugInformation } from '../data/plugInformation.js';
import type { PlugBleAdvertisement, VerifiedPlugBleCandidate } from '../data/plugBleOnboarding.js';
import type { SavedBlePlug } from '../data/savedBlePlug.js';
import { readSavedBlePlugInformation } from './readSavedBlePlugInformation.js';

const plug: SavedBlePlug = {
  physicalId: 'shellyplugsg3-aabbccddeeff',
  name: 'Growbox fan',
  bleDeviceId: 'stale-locator',
  advertisementName: 'ShellyPlugSG3-AABBCCDDEEFF',
  model: 'S3PL-00112EU',
  generation: 3,
  firmwareId: '1.7.5',
  matterEnabled: false
};

const information = { deviceInfo: { id: plug.physicalId }, status: {} } as PlugInformation;
const recoverable = () =>
  new BlePlugReadError({
    kind: 'shelly-offline',
    userMessageKey: 'errors.shellyOffline',
    technicalMessage: 'stale GATT locator',
    retryable: true
  });
const candidate: PlugBleAdvertisement = { deviceId: 'fresh-locator', name: 'Shelly', rssi: -45 };
const verified: VerifiedPlugBleCandidate = {
  bleDeviceId: 'fresh-locator',
  advertisementName: 'Shelly',
  rssi: -45,
  physicalId: plug.physicalId,
  model: plug.model,
  generation: plug.generation,
  firmwareId: plug.firmwareId,
  matterEnabled: plug.matterEnabled
};

describe('readSavedBlePlugInformation', () => {
  it('uses a healthy locator without rediscovery', async () => {
    const readInformation = vi.fn(async () => information);
    const scanCandidates = vi.fn(async () => [] as PlugBleAdvertisement[]);

    await expect(
      readSavedBlePlugInformation(
        plug,
        { persistLocator: vi.fn() },
        { readInformation, scanCandidates }
      )
    ).resolves.toBe(information);

    expect(readInformation).toHaveBeenCalledOnce();
    expect(scanCandidates).not.toHaveBeenCalled();
  });

  it('recovers a stale locator and retries the same read once', async () => {
    const readInformation = vi.fn(async (target: Pick<SavedBlePlug, 'bleDeviceId'>) => {
      if (target.bleDeviceId === plug.bleDeviceId) throw recoverable();
      return information;
    });
    const persistLocator = vi.fn();

    await expect(
      readSavedBlePlugInformation(
        plug,
        { persistLocator },
        {
          readInformation,
          scanCandidates: async () => [candidate],
          inspectCandidate: async () => verified
        }
      )
    ).resolves.toBe(information);

    expect(persistLocator).toHaveBeenCalledWith(plug.physicalId, 'fresh-locator');
    expect(readInformation).toHaveBeenCalledTimes(2);
    expect(readInformation.mock.calls[1]?.[0]).toMatchObject({ bleDeviceId: 'fresh-locator' });
  });

  it('does not scan for a non-recoverable read failure', async () => {
    const error = new Error('identity mismatch');
    const scanCandidates = vi.fn(async () => [candidate]);

    await expect(
      readSavedBlePlugInformation(
        plug,
        { persistLocator: vi.fn() },
        {
          readInformation: async () => { throw error; },
          scanCandidates
        }
      )
    ).rejects.toBe(error);

    expect(scanCandidates).not.toHaveBeenCalled();
  });
});
""")

